// French audio for the lessons. Each phrase has a recording generated by
// scripts/learn-media.mjs (native-sounding neural voices) under
// /learn/audio/<key>.mp3; the list of recordings that exist is
// audio-manifest.json. Only these recordings are played: never the browser's
// synthetic voice.
import { useSyncExternalStore } from 'react';
import manifest from './audio-manifest.json';
import type { Voice } from './types';

const AVAILABLE = new Set<string>((manifest as { keys: string[] }).keys);

// Single words the voice mistakes for a homophone when said alone (checked by
// transcription): it is given a spelling that sounds right. Only the audio
// changes, never the text shown.
const SAY_AS: Record<string, string> = { mes: 'mé' };

/** Words the voice cannot say alone without a mistake: no recording (no speaker button). */
export const NO_AUDIO = new Set(['gris', 'pis', 'y a', 'si']);

/** Normalised text: what decides whether two phrases share a recording. */
export const normalizeForAudio = (text: string) => {
  const t = text
    .replace(/\*\*|__/g, '')
    .replace(/\s*→\s*/g, ', ')
    .replace(/…(?=\s*\p{L})/gu, ' ')
    .replace(/[«»↗↘]/g, '')
    .replace(/\s+\/\s+/g, ', ')
    // Grammar notes in brackets are not read: « l’aube (f.) », « le soccer (Canada) ».
    .replace(/\s*\([^)]*\)\s*$/, '')
    .replace(/\s+/g, ' ')
    .trim();
  return SAY_AS[t] ?? t;
};

/** FNV-1a, 32 bits, base 36. The media script uses the same function. */
export function audioKey(text: string, voice: Voice = 'f'): string {
  const s = `${voice}|${normalizeForAudio(text)}`;
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h.toString(36);
}

export const hasRecording = (text: string, voice: Voice = 'f') => AVAILABLE.has(audioKey(text, voice));

// ── What is playing (for the speaker buttons) ──
let playing: string | null = null;
const listeners = new Set<() => void>();
const setPlaying = (k: string | null) => { playing = k; listeners.forEach(l => l()); };
export function usePlaying(text: string, voice: Voice = 'f') {
  const key = audioKey(text, voice);
  return useSyncExternalStore(
    l => { listeners.add(l); return () => { listeners.delete(l); }; },
    () => playing === key,
    () => false,
  );
}

let current: HTMLAudioElement | null = null;
let muted = false;
export const setMuted = (m: boolean) => { muted = m; if (m) stop(); };
export const isMuted = () => muted;

export function stop() {
  if (current) { current.pause(); current = null; }
  setPlaying(null);
}

/** Plays a French phrase. Resolves when it ends (or fails). */
export function speak(text: string, opts: { voice?: Voice; rate?: number } = {}): Promise<void> {
  const voice = opts.voice ?? 'f';
  const rate = opts.rate ?? 1;
  stop();
  if (muted || typeof window === 'undefined') return Promise.resolve();
  const key = audioKey(text, voice);
  setPlaying(key);
  const done = () => { if (playing === key) setPlaying(null); };

  // Only real recordings: the browser's synthetic voice is never used.
  const synth = () => { done(); return Promise.resolve(); };

  if (!AVAILABLE.has(key)) return synth();
  return new Promise<void>(resolve => {
    const a = new Audio(`/learn/audio/${key}.mp3`);
    current = a;
    a.playbackRate = rate;
    a.onended = () => { done(); resolve(); };
    a.onerror = () => { synth().then(resolve); };
    a.play().catch(() => { synth().then(resolve); });
  });
}

/** Plays phrases one after the other (dialogues). */
export async function speakSequence(items: { text: string; voice?: Voice }[], onLine?: (i: number) => void, signal?: { cancelled: boolean }) {
  for (let i = 0; i < items.length; i++) {
    if (signal?.cancelled) return;
    onLine?.(i);
    await speak(items[i].text, { voice: items[i].voice });
  }
}

// ── Little sound effects, synthesised (no files) ──
let ctx: AudioContext | null = null;
export function chime(kind: 'right' | 'wrong' | 'done') {
  if (muted || typeof window === 'undefined') return;
  try {
    ctx = ctx ?? new (window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext)();
    const notes = kind === 'right' ? [660, 880] : kind === 'wrong' ? [330, 262] : [523, 659, 784, 1046];
    notes.forEach((f, i) => {
      const o = ctx!.createOscillator();
      const g = ctx!.createGain();
      o.type = kind === 'wrong' ? 'triangle' : 'sine';
      o.frequency.value = f;
      const t = ctx!.currentTime + i * 0.09;
      g.gain.setValueAtTime(0.0001, t);
      g.gain.exponentialRampToValueAtTime(kind === 'wrong' ? 0.05 : 0.07, t + 0.02);
      g.gain.exponentialRampToValueAtTime(0.0001, t + 0.28);
      o.connect(g).connect(ctx!.destination);
      o.start(t);
      o.stop(t + 0.3);
    });
  } catch { /* no audio */ }
}
